result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "app.py", "content": """"JWT key rotation service: RS256 signing with a JWKS-style public key endpoint."""

import base64
import os
import time
import uuid
from dataclasses import dataclass, field

import jwt
from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import rsa
from fastapi import Depends, FastAPI, Header, HTTPException
from fastapi.responses import JSONResponse

ADMIN_KEY = os.environ.get("ADMIN_KEY", "super-secret-admin-key")
MAX_ACTIVE_KEYS = 2  # current + one previous kept for verification

app = FastAPI(title="JWT Key Rotation Service")


def _b64url_uint(value: int) -> str:
    """Base64url-encode an integer without padding (JWA 'n'/'e' encoding)."""
    byte_length = (value.bit_length() + 7) // 8
    raw = value.to_bytes(byte_length, "big")
    return base64.urlsafe_b64encode(raw).rstrip(b"=").decode("ascii")


def _generate_keypair():
    return rsa.generate_private_key(public_exponent=65537, key_size=2048)


@dataclass
class SigningKey:
    kid: str
    private_key: rsa.RSAPrivateKey
    activated_at: float = field(default_factory=time.time)

    @property
    def public_jwk(self) -> dict:
        pub = self.private_key.public_key()
        numbers = pub.public_numbers()
        return {
            "kty": "RSA",
            "use": "sig",
            "alg": "RS256",
            "kid": self.kid,
            "n": _b64url_uint(numbers.n),
            "e": _b64url_uint(numbers.e),
        }


class KeyRing:
    """Holds the active signing keys. Index -1 is the current signing key."""

    def __init__(self) -> None:
        self._keys: list[SigningKey] = []
        self._add_new_key()

    @property
    def keys(self) -> list[SigningKey]:
        return list(self._keys)

    @property
    def current(self) -> SigningKey:
        return self._keys[-1]

    def get(self, kid: str) -> SigningKey | None:
        return next((k for k in self._keys if k.kid == kid), None)

    def rotate(self) -> SigningKey:
        """Generate a new keypair, keep the previous for verification, retire the oldest."""
        new_key = self._add_new_key()
        while len(self._keys) > MAX_ACTIVE_KEYS:
            self._keys.pop(0)
        return new_key

    def _add_new_key(self) -> SigningKey:
        key = SigningKey(kid=uuid.uuid4().hex, private_key=_generate_keypair())
        self._keys.append(key)
        return key


keyring = KeyRing()


def issue_token(sub: str, expires_in: int = 3600) -> str:
    now = int(time.time())
    payload = {"sub": sub, "iat": now, "exp": now + expires_in}
    return jwt.encode(payload, _private_pem(keyring.current), algorithm="RS256", headers={"kid": keyring.current.kid})


def verify_token(token: str) -> dict:
    """Accept tokens signed by any still-active kid; reject unknown/retired kids."""
    try:
        header = jwt.get_unverified_header(token)
    except jwt.PyJWTError as exc:
        raise HTTPException(status_code=401, detail="malformed token") from exc
    kid = header.get("kid")
    if not kid:
        raise HTTPException(status_code=401, detail="token missing kid")
    key = keyring.get(kid)
    if key is None:
        raise HTTPException(status_code=401, detail="unknown or retired key")
    try:
        return jwt.decode(token, _public_pem(key), algorithms=["RS256"])
    except jwt.PyJWTError as exc:
        raise HTTPException(status_code=401, detail="invalid token") from exc


def _private_pem(key: SigningKey) -> bytes:
    return key.private_key.private_bytes(
        serialization.Encoding.PEM,
        serialization.PrivateFormat.PKCS8,
        serialization.NoEncryption(),
    )


def _public_pem(key: SigningKey) -> bytes:
    return key.private_key.public_key().public_bytes(
        serialization.Encoding.PEM,
        serialization.PublicFormat.SubjectPublicKeyInfo,
    )


# Fingerprint used only to prove admin possession of the admin key in tests/logs.
_admin_fingerprint = hashes.Hash(hashes.SHA256())


def require_admin(x_admin_key: str = Header(default="")) -> None:
    if x_admin_key != ADMIN_KEY:
        raise HTTPException(status_code=403, detail="admin key required")


@app.post("/token")
def post_token(sub: str = "user"):
    """Issue a token signed by the currently active kid."""
    return {"access_token": issue_token(sub), "token_type": "bearer", "kid": keyring.current.kid}


@app.get("/verify")
def get_verify(authorization: str = Header(default="")):
    if not authorization.startswith("Bearer "):
        raise HTTPException(status_code=401, detail="Bearer token required")
    claims = verify_token(authorization.removeprefix("Bearer ").strip())
    return {"valid": True, "claims": claims}


@app.get("/.well-known/keys")
def well_known_keys():
    """JWKS-style publication of public keys only — never private material."""
    return JSONResponse(content={"keys": [k.public_jwk for k in keyring.keys]})


@app.post("/admin/rotate")
def admin_rotate(_: None = Depends(require_admin)):
    new_key = keyring.rotate()
    return {
        "rotated_to_kid": new_key.kid,
        "active_kids": [k.kid for k in keyring.keys],
        "retired_count": max(0, len(keyring.keys) - MAX_ACTIVE_KEYS),
    }
"})
